async function loadAlerts(force=false){const a=alertState();if(a.busy||(!force&&Date.now()-a.at<15000))return;a.busy=true;try{const d=state.mode==='demo'?(a.demo||(a.demo=demoAlerts())):await api('alerts');Object.assign(a,{alerts:d.alerts||[],open:d.open||0,config:d.config||a.config,error:''});a.at=Date.now()}catch(e){a.error=e.message||'Alarme konnten nicht geladen werden.'}finally{a.busy=false;a.tried=Date.now()}if(state.authenticated)(typeof renderLive==='function'?renderLive:render)()}
