setInterval(()=>{if(state.authenticated&&!document.hidden)loadAlerts()},30000);
if(typeof document.addEventListener==='function')document.addEventListener('click',e=>{if(typeof innerWidth==='number'&&(innerWidth<=900||state.navPinned===false)&&state.navCollapsed&&(e.target.closest?.('.prism-sidebar [data-nav]')||e.target.classList?.contains('prism-layout'))){state.navCollapsed=false;if(e.target.classList?.contains('prism-layout'))render()}},true);

/* Nutanix-style navigation: app switcher, navigation bar groups, pinning and global search */
try{const pinned=localStorage.getItem('orbit-nav-pinned');if(pinned!==null)state.navPinned=pinned==='1';state.navGroupsClosed=JSON.parse(localStorage.getItem('orbit-nav-groups')||'{}')||{}}catch{}
function closeMenus(except){for(const d of document.querySelectorAll('details.app-switcher[open],details.user-menu[open],details.action-menu[open]'))if(d!==except)d.removeAttribute('open')}
function goSearchResult(r){if(!r)return;const input=$('#global-search');if(input){input.value='';input.blur()}const box=$('#global-search-results');if(box)box.hidden=true;if(r.vm)vmDetails(r.vm);else if(r.settings){state.settingsTab=r.settings;nav('settings')}else if(r.nav)nav(r.nav)}
function paintSearch(input){const box=$('#global-search-results');if(!box)return;const results=globalSearchResults(input.value);state.searchResults=results;state.searchIndex=Math.min(state.searchIndex||0,Math.max(0,results.length-1));if(!input.value.trim()){box.hidden=true;box.innerHTML='';return}box.hidden=false;box.innerHTML=results.length?results.map((r,i)=>`<button type="button" role="option" class="gs-item ${i===state.searchIndex?'is-active':''}" data-search-index="${i}" aria-selected="${i===state.searchIndex}">${icon(r.icon)}<span class="gs-label">${esc(r.label)}</span>${r.meta?`<span class="gs-meta">${esc(r.meta)}</span>`:''}<span class="gs-kind">${r.kind}</span></button>`).join(''):`<div class="gs-empty">Keine Treffer für „${esc(input.value)}“</div>`;for(const b of box.querySelectorAll('[data-search-index]'))b.onmousedown=e=>{e.preventDefault();goSearchResult(state.searchResults[+b.dataset.searchIndex])}}
function bindNavigation(){
 $$('[data-app]').forEach(b=>b.onclick=()=>{closeMenus();const a=orbitApps.find(x=>x.id===b.dataset.app);if(a)nav(a.home)});
 $$('[data-settings-nav]').forEach(b=>b.onclick=()=>{closeMenus();state.settingsTab=b.dataset.settingsNav;nav('settings')});
 $$('[data-nav-group]').forEach(b=>b.onclick=()=>{const g=b.dataset.navGroup,c=state.navGroupsClosed||(state.navGroupsClosed={});c[g]=!c[g];try{localStorage.setItem('orbit-nav-groups',JSON.stringify(c))}catch{}render()});
 $$('[data-nav-pin]').forEach(b=>b.onclick=()=>{state.navPinned=!navPinned();state.navCollapsed=false;try{localStorage.setItem('orbit-nav-pinned',state.navPinned?'1':'0')}catch{}render()});
 for(const d of document.querySelectorAll('details.app-switcher,details.user-menu'))d.ontoggle=()=>{if(d.open)closeMenus(d)};
 const input=$('#global-search');if(input){input.oninput=()=>{state.searchIndex=0;paintSearch(input)};input.onfocus=()=>{if(input.value)paintSearch(input)};input.onblur=()=>setTimeout(()=>{const box=$('#global-search-results');if(box&&document.activeElement!==input)box.hidden=true},120);input.onkeydown=e=>{const n=(state.searchResults||[]).length;if(e.key==='ArrowDown'&&n){e.preventDefault();state.searchIndex=((state.searchIndex||0)+1)%n;paintSearch(input)}else if(e.key==='ArrowUp'&&n){e.preventDefault();state.searchIndex=((state.searchIndex||0)-1+n)%n;paintSearch(input)}else if(e.key==='Enter'){e.preventDefault();goSearchResult((state.searchResults||[])[state.searchIndex||0])}else if(e.key==='Escape'){input.value='';paintSearch(input);input.blur()}}}
}
if(typeof document.addEventListener==='function'){
 document.addEventListener('click',e=>{if(!e.target.closest?.('details.app-switcher,details.user-menu'))for(const d of document.querySelectorAll('details.app-switcher[open],details.user-menu[open]'))d.removeAttribute('open')});
 document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!(typeof modal!=='undefined'&&modal.open)){const i=$('#global-search');if(i){e.preventDefault();i.focus()}}});
}

/* Accounts: users and roles (admin), two-factor authentication and API tokens (self-service) */
const roleLabels={admin:'Administrator',operator:'Operator',viewer:'Nur lesen'};
const roleHelp={admin:'Alles, inkl. Verbindungen, Benutzer, Systemeinstellungen und Löschen von Gästen.',operator:'Gäste betreiben: Start/Stopp, Snapshots, Backups, Migration, Klonen, Konsole, Marketplace.',viewer:'Nur lesen. Eigenes Passwort, 2FA und Tokens verwalten.'};
const isAdmin=()=>state.mode==='demo'||state.user?.role==='admin';
function accountState(){return state.account||(state.account={users:null,tokens:null,me:null,newToken:null,totpSetup:null,busy:false})}
async function loadAccount(force=false){const a=accountState();if(a.busy||(!force&&a.loaded))return;a.busy=true;try{if(state.mode==='demo'){a.me={username:'admin',role:'admin',totp:false};a.tokens=a.tokens||[];a.users=a.users||[{id:'u1',username:'admin',role:'admin',disabled:false,totp:false,self:true,created:Date.now()/1000-86400*30},{id:'u2',username:'olga',role:'operator',disabled:false,totp:true,created:Date.now()/1000-86400*5},{id:'u3',username:'audit',role:'viewer',disabled:true,totp:false,created:Date.now()/1000-86400}]}else{a.me=await api('me');a.tokens=await api('account/tokens');a.users=isAdmin()?await api('users'):null}a.loaded=true;a.error=''}catch(e){a.error=e.message}finally{a.busy=false}if(state.page==='settings')(typeof renderLive==='function'?renderLive:render)()}
function accountExtras(){const a=accountState(),me=a.me||{};return `<section class="settings-card"><div class="panelhead"><div><h2>Zwei-Faktor-Anmeldung (TOTP)</h2><p>${me.totp?'Aktiv. Bei der Anmeldung wird zusätzlich ein Code aus der Authenticator-App abgefragt.':'Schützt das Konto zusätzlich mit einem Code aus einer Authenticator-App (z. B. Microsoft/Google Authenticator, 1Password, Bitwarden).'}</p></div>${me.totp?'<button data-totp-disable>2FA deaktivieren</button>':'<button class="primary" data-totp-setup>2FA einrichten</button>'}</div>${a.totpSetup?`<div class="totp-setup"><p>Schlüssel in der Authenticator-App manuell hinzufügen (Kontoname: <b>${esc(me.username||'')}</b>, zeitbasiert, 6 Stellen):</p><code class="totp-secret">${esc(a.totpSetup.secret.replace(/(.{4})/g,'$1 ').trim())}</code><p class="muted">Oder diesen Link auf dem Smartphone öffnen: <a href="${esc(a.totpSetup.uri)}">otpauth-Link</a></p><form id="totp-enable-form" class="inline-form">${field('Code aus der App','code','',{placeholder:'123456',autocomplete:'one-time-code'})}<button class="primary">Aktivieren</button></form><div class="hint error" data-totp-error></div></div>`:''}</section>`
+`<section class="settings-card"><div class="panelhead"><div><h2>API-Tokens</h2><p>Für Skripte, Ansible, Terraform oder Monitoring. Aufruf mit <code>Authorization: Bearer orb_…</code>. Ein Token hat die Rechte deines Kontos; „Nur lesen“ beschränkt es zusätzlich.</p></div><button class="primary" data-token-new>${icon('plus')} Token erstellen</button></div>${a.newToken?`<div class="hint warn token-once"><b>Neues Token „${esc(a.newToken.name)}“ – wird nur jetzt angezeigt:</b><code>${esc(a.newToken.token)}</code></div>`:''}${(a.tokens||[]).length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Rechte</th><th>Erstellt</th><th>Läuft ab</th><th>Zuletzt genutzt</th><th></th></tr></thead><tbody>${a.tokens.map(t=>`<tr><td><b>${esc(t.name)}</b></td><td>${t.scope==='read'?'Nur lesen':'Lesen & schreiben'}</td><td class="num">${when(t.created)}</td><td class="num">${t.expires?when(t.expires):'nie'}</td><td class="num">${t.last_used?when(t.last_used):'—'}</td><td><button class="text-button danger" data-token-revoke="${esc(t.id)}">Widerrufen</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Noch keine Tokens.</p>'}</section>`}
function usersView(){const a=accountState();if(!isAdmin())return '<section class="settings-card"><p>Nur für Administratoren.</p></section>';return ssoView()+`<section class="settings-card"><div class="panelhead"><div><h2>Benutzer & Rollen</h2><p>Jede Person bekommt ein eigenes Konto. Aktionen und Änderungen werden mit Benutzernamen im Audit-Log und in den Aufgaben protokolliert.</p></div><button class="primary" data-user-edit="">${icon('plus')} Benutzer anlegen</button></div>${a.error?`<div class="hint error">${esc(a.error)}</div>`:''}<div class="role-grid">${Object.entries(roleLabels).map(([k,l])=>`<div class="role-card"><b>${l}</b><small>${roleHelp[k]}</small></div>`).join('')}</div>${a.users?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Benutzer</th><th>Rolle</th><th>Status</th><th>2FA</th><th>Angelegt</th><th></th></tr></thead><tbody>${a.users.map(u=>`<tr><td><b>${esc(u.username)}</b>${u.self?' <small class="muted">(du)</small>':''}</td><td>${roleLabels[u.role]||esc(u.role)}</td><td>${u.disabled?statusTag('stopped').replace('Gestoppt','Deaktiviert'):statusTag('online').replace('Online','Aktiv')}</td><td>${u.totp?'Aktiv':'—'}</td><td class="num">${when(u.created)}</td><td>${u.self?'':`<button class="text-button" data-user-edit="${esc(u.id)}">Bearbeiten</button> <button class="text-button danger" data-user-delete="${esc(u.id)}">Löschen</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<div class="loading">Benutzer werden geladen …</div>'}</section>`}
function userModal(id){const a=accountState(),u=(a.users||[]).find(x=>x.id===id),editing=!!u;openModal('BENUTZER',editing?u.username+' bearbeiten':'Benutzer anlegen',`<form id="user-form">${editing?'':field('Benutzername','username','',{pattern:'[a-z][a-z0-9._\\-]{1,31}',placeholder:'vorname.nachname',autocomplete:'off'})}${selectField('Rolle','role',Object.entries(roleLabels).map(([k,l])=>option(k,l,(u?.role||'operator')===k)).join(''))}${field(editing?'Neues Passwort (optional)':'Passwort','password','',{type:'password',autocomplete:'new-password',optional:editing,help:'Mindestens 12 Zeichen.'})}${editing?`<label class="checkbox"><input type="checkbox" name="disabled" ${u.disabled?'checked':''}> Konto deaktivieren (meldet sofort ab)</label>${u.totp?'<label class="checkbox"><input type="checkbox" name="reset_totp"> 2FA zurücksetzen (z. B. bei verlorenem Smartphone)</label>':''}`:''}<p class="muted" data-role-help>${roleHelp[u?.role||'operator']}</p><div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary">Speichern</button></div></form>`);
const form=$('#user-form');form.elements.role.onchange=()=>{form.querySelector('[data-role-help]').textContent=roleHelp[form.elements.role.value]};form.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));setModalBusy(true);try{if(state.mode==='demo'){if(editing)Object.assign(u,{role:d.role,disabled:d.disabled==='on'});else a.users.push({id:newRequestKey(),username:d.username,role:d.role,disabled:false,totp:false,created:Date.now()/1000})}else if(editing)await api('users/'+encodeURIComponent(id),{method:'POST',body:JSON.stringify({role:d.role,disabled:d.disabled==='on',password:d.password||'',reset_totp:d.reset_totp==='on'})});else await api('users',{method:'POST',body:JSON.stringify({username:d.username,role:d.role,password:d.password})});closeModal(true);toast('Benutzer gespeichert.');await loadAccount(true)}catch(err){setModalBusy(false);formError(err.message)}}}
function bindAccounts(){
 if(state.page==='settings'&&['account','users'].includes(state.settingsTab)&&!accountState().loaded&&!accountState().busy)loadAccount();
 $$('[data-user-edit]').forEach(b=>b.onclick=()=>userModal(b.dataset.userEdit));
 $$('[data-user-delete]').forEach(b=>b.onclick=()=>{const a=accountState(),u=a.users.find(x=>x.id===b.dataset.userDelete);if(!u)return;openModal('BENUTZER',u.username+' löschen',`<form id="user-delete-form"><p>Sitzungen und API-Tokens dieses Kontos werden ebenfalls gelöscht. Einträge im Audit-Log bleiben erhalten.</p>${field('Zur Bestätigung den Benutzernamen eingeben','confirm_name','',{placeholder:u.username})}<div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary">Löschen</button></div></form>`);$('#user-delete-form').onsubmit=async e=>{e.preventDefault();const confirm=new FormData(e.target).get('confirm_name');setModalBusy(true);try{if(state.mode==='demo'){if(confirm!==u.username)throw new Error('Benutzernamen zur Bestätigung eingeben.');a.users=a.users.filter(x=>x!==u)}else await api('users/'+encodeURIComponent(u.id)+'/delete',{method:'POST',body:JSON.stringify({confirm_name:confirm})});closeModal(true);toast('Benutzer gelöscht.');await loadAccount(true)}catch(err){setModalBusy(false);formError(err.message)}}});
 $$('[data-totp-setup]').forEach(b=>b.onclick=async()=>{try{accountState().totpSetup=state.mode==='demo'?{secret:'JBSWY3DPEHPK3PXPJBSWY3DPEHPK3PXP',uri:'otpauth://totp/Orbit%20Central:admin?secret=JBSWY3DPEHPK3PXP'}:await api('account/totp/setup',{method:'POST',body:'{}'});render()}catch(e){toast(e.message)}});
 const totp=$('#totp-enable-form');if(totp)totp.onsubmit=async e=>{e.preventDefault();const code=new FormData(totp).get('code');try{if(state.mode!=='demo')await api('account/totp/enable',{method:'POST',body:JSON.stringify({code})});accountState().totpSetup=null;toast('Zwei-Faktor-Anmeldung aktiviert.');await loadAccount(true)}catch(err){const el=$('[data-totp-error]');if(el)el.textContent=err.message}};
 $$('[data-totp-disable]').forEach(b=>b.onclick=()=>{openModal('ZWEI-FAKTOR','2FA deaktivieren',`<form id="totp-disable-form">${field('Passwort','password','',{type:'password',autocomplete:'current-password'})}${field('Aktueller Code','code','',{autocomplete:'one-time-code'})}<div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary">Deaktivieren</button></div></form>`);$('#totp-disable-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));setModalBusy(true);try{if(state.mode!=='demo')await api('account/totp/disable',{method:'POST',body:JSON.stringify(d)});closeModal(true);toast('2FA deaktiviert.');await loadAccount(true)}catch(err){setModalBusy(false);formError(err.message)}}});
 $$('[data-token-new]').forEach(b=>b.onclick=()=>{openModal('API-TOKEN','Token erstellen',`<form id="token-form">${field('Name','name','',{placeholder:'z. B. ansible-prod'})}<div class="formgrid">${selectField('Rechte','scope',option('read','Nur lesen',true)+option('write','Lesen & schreiben (Rechte deines Kontos)'))}${selectField('Gültig','days',option(30,'30 Tage',true)+option(90,'90 Tage')+option(365,'1 Jahr')+option(0,'Unbegrenzt'))}</div><div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary">Erstellen</button></div></form>`);$('#token-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));setModalBusy(true);try{const t=state.mode==='demo'?{id:newRequestKey(),token:'orb_demo_'+newRequestKey().replace(/-/g,''),name:d.name,scope:d.scope,expires:+d.days?Date.now()/1000+d.days*86400:0}:await api('account/tokens',{method:'POST',body:JSON.stringify({name:d.name,scope:d.scope,days:+d.days})});const a=accountState();a.newToken=t;if(state.mode==='demo')a.tokens=[{...t,created:Date.now()/1000,last_used:0},...(a.tokens||[])];closeModal(true);await loadAccount(true);render()}catch(err){setModalBusy(false);formError(err.message)}}});
 $$('[data-token-revoke]').forEach(b=>b.onclick=async()=>{if(!confirm('Token widerrufen? Skripte mit diesem Token funktionieren danach nicht mehr.'))return;try{const a=accountState();if(state.mode==='demo')a.tokens=a.tokens.filter(t=>t.id!==b.dataset.tokenRevoke);else await api('account/tokens/'+encodeURIComponent(b.dataset.tokenRevoke),{method:'DELETE'});a.newToken=null;toast('Token widerrufen.');await loadAccount(true)}catch(e){toast(e.message)}});
}

/* Single sign-on (OIDC) configuration */
function ssoView(){const a=accountState(),c=a.sso;if(!c)return '';return `<section class="settings-card"><div class="panelhead"><div><h2>Anmeldung mit Firmenkonto (OpenID Connect)</h2><p>Microsoft Entra ID, Keycloak, Authentik, Google Workspace und andere OIDC-Anbieter. Benutzer werden bei der ersten Anmeldung angelegt; die Rolle folgt bei jeder Anmeldung den Gruppen.</p></div>${c.enabled?statusTag('online').replace('Online','Aktiv'):statusTag('stopped').replace('Gestoppt','Aus')}</div><form id="sso-form"><div class="formgrid">${field('Issuer-URL','issuer',c.issuer||'',{optional:true,placeholder:'https://login.microsoftonline.com/<tenant>/v2.0'})}${field('Client-ID','client_id',c.client_id||'',{optional:true})}${field('Client-Secret','client_secret','',{optional:true,type:'password',placeholder:c.has_secret?'gespeichert – leer lassen zum Beibehalten':''})}${field('Text auf dem Anmelde-Button','button_label',c.button_label||'',{optional:true})}${selectField('Benutzername aus','username_claim',[['preferred_username','preferred_username'],['email','email'],['upn','upn (Entra ID)'],['sub','sub']].map(([k,l])=>option(k,l,c.username_claim===k)).join(''))}${field('Gruppen-Claim','groups_claim',c.groups_claim||'groups',{optional:true})}${field('Gruppe → Administrator','admin_group',c.admin_group||'',{optional:true,placeholder:'Gruppenname oder Objekt-ID'})}${field('Gruppe → Operator','operator_group',c.operator_group||'',{optional:true})}${field('Gruppe → Nur lesen','viewer_group',c.viewer_group||'',{optional:true})}${selectField('Ohne passende Gruppe','default_role',option('','Zugriff verweigern',!c.default_role)+option('viewer','Nur lesen',c.default_role==='viewer')+option('operator','Operator',c.default_role==='operator'))}</div><p class="muted">Redirect-URI beim Anbieter eintragen: <code>${esc(c.redirect_uri)}</code></p><label class="checkbox"><input type="checkbox" name="enabled" ${c.enabled?'checked':''}> Anmeldung mit Firmenkonto aktivieren</label><div class="hint error" data-sso-error></div><div class="settings-save"><span>Lokale Konten bleiben als Notfallzugang erhalten.</span><button class="primary">Speichern</button></div></form></section>`}
async function loadSSO(){const a=accountState();if(a.ssoLoading||a.sso)return;a.ssoLoading=true;try{a.sso=state.mode==='demo'?{enabled:false,issuer:'',client_id:'',has_secret:false,button_label:'Mit Firmenkonto anmelden',username_claim:'preferred_username',groups_claim:'groups',redirect_uri:location.origin+'/api/oidc/callback'}:await api('users/sso')}catch(e){a.error=e.message}finally{a.ssoLoading=false}if(state.page==='settings')(typeof renderLive==='function'?renderLive:render)()}
function bindSSO(){if(state.page==='settings'&&state.settingsTab==='users'&&isAdmin())loadSSO();const f=$('#sso-form');if(f)f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));d.enabled=d.enabled==='on';const btn=f.querySelector('button.primary');btn.disabled=true;try{accountState().sso=state.mode==='demo'?{...accountState().sso,...d,client_secret:undefined,has_secret:!!d.client_secret||accountState().sso.has_secret}:await api('users/sso',{method:'POST',body:JSON.stringify(d)});toast('Firmenanmeldung gespeichert.');render()}catch(err){const el=f.querySelector('[data-sso-error]');if(el)el.textContent=err.message}finally{btn.disabled=false}}}

/* Backup schedules (vzdump jobs) */
const schedulePresets=[['01:00','Täglich 01:00'],['mon..fri 21:30','Werktags 21:30'],['sat 02:00','Samstags 02:00'],['sun 03:00','Sonntags 03:00'],['*-*-01 03:00','Monatlich am 1. um 03:00'],['custom','Benutzerdefiniert …']];
const keepFields=[['keep-last','Letzte'],['keep-hourly','Stündlich'],['keep-daily','Täglich'],['keep-weekly','Wöchentlich'],['keep-monthly','Monatlich'],['keep-yearly','Jährlich']];
function scheduleText(s){const p=schedulePresets.find(x=>x[0]===s);return p?p[1]:String(s||'—')}
function pruneText(p){if(!p||/keep-all=1/.test(p))return 'Alle behalten';const names=Object.fromEntries(keepFields);return String(p).split(',').map(x=>{const[k,v]=x.split('=');return `${names[k]||k} ${v}`}).join(' · ')}
function jobSelection(j){return +j.all?('Alle Gäste'+(j.exclude?` außer ${j.exclude}`:'')):j.pool?'Pool '+j.pool:'VMID '+(j.vmid||'—')}
function backupStorages(cid){return [...new Set(state.resources.filter(r=>r.type==='storage'&&r.connection_id===cid&&String(r.content||'').includes('backup')).map(r=>r.storage))].concat(state.mode==='demo'?['pbs-backup']:[]).filter((v,i,a)=>a.indexOf(v)===i)}
function backupJobsPanel(c,result){const admin=isAdmin(),rows=result?.ok?result.data:[];return `<section class="panel module-panel"><div class="table-toolbar"><h2>Backup-Zeitpläne</h2>${admin&&c.kind!=='pbs'?`<button class="primary" data-backup-job-edit="${esc(c.id)}|">${icon('plus')} Zeitplan anlegen</button>`:''}</div>${result&&!result.ok?`<div class="hint error">${esc(result.error)}</div>`:''}${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Zeitplan</th><th>Gäste</th><th>Storage</th><th>Modus</th><th>Aufbewahrung</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(j=>`<tr><td><b>${esc(scheduleText(j.schedule))}</b><small class="muted">${esc(j.id||'')}${j.comment?' · '+esc(j.comment):''}</small></td><td>${esc(jobSelection(j))}</td><td>${esc(j.storage||'—')}</td><td>${esc({snapshot:'Snapshot',suspend:'Suspend',stop:'Stopp'}[j.mode]||j.mode||'—')}</td><td class="muted">${esc(pruneText(j['prune-backups']))}</td><td>${j.enabled===0||j.enabled==='0'?statusTag('stopped').replace('Gestoppt','Pausiert'):statusTag('online').replace('Online','Aktiv')}</td><td>${admin?`<button class="text-button" data-backup-job-edit="${esc(c.id)}|${esc(j.id)}">Bearbeiten</button> <button class="text-button danger" data-backup-job-delete="${esc(c.id)}|${esc(j.id)}">Löschen</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('lock','Keine Backup-Zeitpläne','Ohne Zeitplan werden Gäste nicht automatisch gesichert.')}</section>`}
function findBackupJob(cid,id){const mods=state.modules.protection||[];const m=mods.find(x=>x.connection?.id===cid);const list=m?.data?.backup_jobs?.ok?m.data.backup_jobs.data:[];return list.find(j=>j.id===id)}
function backupJobModal(ref){const[cid,id]=ref.split('|'),j=id?findBackupJob(cid,id):null,editing=!!j,stores=backupStorages(cid),prune=Object.fromEntries(String(j?.['prune-backups']||'keep-daily=7,keep-weekly=4').split(',').map(x=>x.split('='))),preset=schedulePresets.some(p=>p[0]===j?.schedule)?j.schedule:(j?'custom':'01:00'),selection=j?(+j.all?'all':j.pool?'pool':'vmids'):'all';
openModal('BACKUP-ZEITPLAN',editing?'Zeitplan bearbeiten':'Zeitplan anlegen',`<form id="backup-job-form"><div class="formgrid">${selectField('Zeitplan','preset',schedulePresets.map(([k,l])=>option(k,l,preset===k)).join(''))}<div data-custom-schedule ${preset==='custom'?'':'hidden'}>${field('Proxmox-Kalenderausdruck','schedule_custom',j?.schedule||'',{optional:true,placeholder:'z. B. mon,wed,fri 22:00'})}</div>${selectField('Backup-Storage','storage',(stores.length?stores:[j?.storage||'']).map(s=>option(s,s,(j?.storage||stores[0])===s)).join(''))}${selectField('Modus','mode',option('snapshot','Snapshot – ohne Unterbrechung',(j?.mode||'snapshot')==='snapshot')+option('suspend','Suspend – kurze Pause',j?.mode==='suspend')+option('stop','Stopp – Gast wird angehalten',j?.mode==='stop'))}</div>
<label>Welche Gäste</label><div class="segmented">${[['all','Alle'],['vmids','Bestimmte VMIDs'],['pool','Pool']].map(([k,l])=>`<label><input type="radio" name="selection" value="${k}" ${selection===k?'checked':''}> ${l}</label>`).join('')}</div>
<div class="formgrid"><div data-sel="all" ${selection==='all'?'':'hidden'}>${field('Ausnehmen (VMIDs, kommagetrennt)','exclude',j?.exclude||'',{optional:true,placeholder:'z. B. 105, 9000'})}</div><div data-sel="vmids" ${selection==='vmids'?'':'hidden'}>${field('VMIDs','vmids',j?.vmid||'',{optional:true,placeholder:'100, 101, 102'})}</div><div data-sel="pool" ${selection==='pool'?'':'hidden'}>${field('Pool','pool',j?.pool||'',{optional:true})}</div><div></div></div>
<label>Aufbewahrung (leer = alle behalten)</label><div class="keep-grid">${keepFields.map(([k,l])=>`<label><span>${l}</span><input type="number" min="0" max="9999" name="${k}" value="${esc(prune[k]||'')}"></label>`).join('')}</div>
<div class="formgrid">${field('E-Mail bei Problemen (optional)','mailto',j?.mailto||'',{optional:true,placeholder:'ops@example.com'})}${field('Kommentar','comment',j?.comment||'',{optional:true})}</div><label class="checkbox"><input type="checkbox" name="enabled" ${!j||+j.enabled!==0?'checked':''}> Zeitplan aktiv</label><div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary">Speichern</button></div></form>`);
const form=$('#backup-job-form');form.elements.preset.onchange=()=>{form.querySelector('[data-custom-schedule]').hidden=form.elements.preset.value!=='custom'};for(const r of form.querySelectorAll('[name=selection]'))r.onchange=()=>{for(const el of form.querySelectorAll('[data-sel]'))el.hidden=el.dataset.sel!==form.elements.selection.value};
form.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form)),body={schedule:d.preset==='custom'?d.schedule_custom:d.preset,storage:d.storage,mode:d.mode,selection:d.selection,exclude:d.exclude,vmids:d.vmids,pool:d.pool,mailto:d.mailto,comment:d.comment,enabled:d.enabled==='on'};for(const[k] of keepFields)if(d[k])body[k]=+d[k];setModalBusy(true);try{if(state.mode==='demo'){const m=(state.modules.protection||[]).find(x=>x.connection?.id===cid);const list=m?.data?.backup_jobs?.data;if(list){const keep=keepFields.filter(([k])=>body[k]).map(([k])=>k+'='+body[k]).join(',');const job={id:id||'backup-'+(list.length+1),schedule:body.schedule,storage:body.storage,mode:body.mode,all:body.selection==='all'?1:0,vmid:body.vmids,pool:body.pool,exclude:body.exclude,enabled:body.enabled?1:0,'prune-backups':keep,comment:body.comment};if(editing)Object.assign(j,job);else list.push(job)}}else await api('connections/'+encodeURIComponent(cid)+'/backup-jobs'+(editing?'/'+encodeURIComponent(id):''),{method:'POST',body:JSON.stringify(body)});closeModal(true);toast('Zeitplan gespeichert.');if(state.mode!=='demo')await loadModule('protection',true);render()}catch(err){setModalBusy(false);formError(err.message)}}}
function bindBackupJobs(){
 $$('[data-backup-job-edit]').forEach(b=>b.onclick=()=>backupJobModal(b.dataset.backupJobEdit));
 $$('[data-backup-job-delete]').forEach(b=>b.onclick=()=>{const[cid,id]=b.dataset.backupJobDelete.split('|');openModal('BACKUP-ZEITPLAN','Zeitplan löschen',`<p>Der Zeitplan <b>${esc(id)}</b> wird gelöscht. Vorhandene Backups bleiben erhalten.</p><div class="modal-foot"><button data-cancel>Abbrechen</button><button class="primary" data-confirm-delete>Löschen</button></div>`);modal.querySelector('[data-confirm-delete]').onclick=async()=>{setModalBusy(true);try{if(state.mode==='demo'){const m=(state.modules.protection||[]).find(x=>x.connection?.id===cid);if(m)m.data.backup_jobs.data=m.data.backup_jobs.data.filter(j=>j.id!==id)}else{await api('connections/'+encodeURIComponent(cid)+'/backup-jobs/'+encodeURIComponent(id),{method:'DELETE'});await loadModule('protection',true)}closeModal(true);toast('Zeitplan gelöscht.');render()}catch(e){setModalBusy(false);toast(e.message)}}});
}

/* History charts (Proxmox RRD) — small multiples, one axis each, crosshair tooltip */
const timeframes=[['hour','1 Stunde'],['day','1 Tag'],['week','1 Woche'],['month','1 Monat'],['year','1 Jahr']];
function rrdState(){return state.rrd||(state.rrd={})}
function demoRRD(kind,timeframe){const step={hour:60,day:1800,week:10800,month:43200,year:604800}[timeframe],now=Date.now()/1000,base=kind==='node'?0.3:0.15;return{points:Array.from({length:70},(_,i)=>{const w=Math.sin(i/6)*.5+.5,t=now-(69-i)*step;return{t,cpu:base+0.25*w*(0.7+0.3*Math.sin(i/2.3)),mem:(0.4+0.2*w)*16*GiB,maxmem:16*GiB,netin:3e6*w+2e5,netout:1.2e6*w+1e5,diskread:6e5*w,diskwrite:9e5*(1-w)+1e5}})}}
async function loadRRD(key,force=false){const c=rrdState(),entry=c[key]||(c[key]={});if(entry.busy||(!force&&entry.at&&Date.now()-entry.at<60000))return;const[kind,cid,node,vmid,timeframe]=key.split('|');entry.busy=true;try{const d=state.mode==='demo'?demoRRD(kind,timeframe):await api('connections/'+encodeURIComponent(cid)+'/rrd?'+new URLSearchParams({kind,node,vmid:vmid||'',timeframe}));entry.points=d.points||[];entry.error='';entry.at=Date.now()}catch(e){entry.error=e.message;entry.at=Date.now()}finally{entry.busy=false}for(const el of document.querySelectorAll(`[data-metrics-key="${CSS.escape(key)}"]`)){const parent=el.parentElement;el.outerHTML=metricsCharts(key);if(parent)bindCharts(parent)}}
const rate=v=>fmtBytes(v)+'/s';
function chartSVG(id,points,series,opts){const W=560,H=150,P={l:44,r:8,t:10,b:22},xs=points.map(p=>p.t),x0=Math.min(...xs),x1=Math.max(...xs),vals=points.flatMap(p=>series.map(s=>s.value(p)).filter(v=>Number.isFinite(v))),max=opts.max??Math.max(1e-9,...vals)*1.15,X=t=>P.l+(t-x0)/(x1-x0||1)*(W-P.l-P.r),Y=v=>P.t+(1-Math.min(v,max)/max)*(H-P.t-P.b),ticks=[0,.5,1].map(f=>f*max),fmtTime=t=>new Date(t*1000).toLocaleString('de-DE',opts.span>172800?{day:'2-digit',month:'2-digit'}:{hour:'2-digit',minute:'2-digit'});
const path=s=>points.map((p,i)=>{const v=s.value(p);return Number.isFinite(v)?`${i&&Number.isFinite(s.value(points[i-1]))?'L':'M'}${X(p.t).toFixed(1)},${Y(v).toFixed(1)}`:''}).join('');
return `<svg class="chart-svg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="${esc(opts.label)}" data-chart="${esc(id)}">${ticks.map(v=>`<line class="chart-grid" x1="${P.l}" x2="${W-P.r}" y1="${Y(v)}" y2="${Y(v)}"/><text class="chart-axis" x="${P.l-6}" y="${Y(v)+3}" text-anchor="end">${esc(opts.fmt(v,true))}</text>`).join('')}${[x0,(x0+x1)/2,x1].map((t,i)=>`<text class="chart-axis" x="${X(t)}" y="${H-6}" text-anchor="${['start','middle','end'][i]}">${esc(fmtTime(t))}</text>`).join('')}${series.map((s,i)=>`<path class="chart-line series-${i+1}" d="${path(s)}"/>`).join('')}<line class="chart-cross" x1="0" x2="0" y1="${P.t}" y2="${H-P.b}" visibility="hidden"/><rect class="chart-hit" x="${P.l}" y="${P.t}" width="${W-P.l-P.r}" height="${H-P.t-P.b}"/></svg>`}
const chartDefs=[{id:'cpu',title:'CPU-Auslastung',max:100,fmt:v=>Math.round(v)+' %',series:[{label:'CPU',value:p=>(p.cpu??NaN)*100}]},{id:'mem',title:'Arbeitsspeicher',max:100,fmt:v=>Math.round(v)+' %',series:[{label:'RAM',value:p=>p.maxmem?p.mem/p.maxmem*100:NaN}]},{id:'net',title:'Netzwerk',fmt:(v,axis)=>axis?fmtBytes(v):rate(v),series:[{label:'Eingang',value:p=>p.netin??NaN},{label:'Ausgang',value:p=>p.netout??NaN}]},{id:'disk',title:'Datenträger-I/O',fmt:(v,axis)=>axis?fmtBytes(v):rate(v),series:[{label:'Lesen',value:p=>p.diskread??NaN},{label:'Schreiben',value:p=>p.diskwrite??NaN}]}];
function metricsCharts(key){const e=rrdState()[key]||{},tf=key.split('|')[4],span={hour:3600,day:86400,week:604800,month:2592000,year:31536000}[tf];if(!e.points){return `<div class="metrics-body" data-live-preserve data-metrics-key="${esc(key)}"><div class="loading">${e.error?esc(e.error):'Verlauf wird geladen …'}</div></div>`}if(!e.points.length)return `<div class="metrics-body" data-live-preserve data-metrics-key="${esc(key)}"><p class="muted">Keine Messdaten für diesen Zeitraum.</p></div>`;
return `<div class="metrics-body" data-live-preserve data-metrics-key="${esc(key)}">${e.error?`<div class="hint warn">${esc(e.error)}</div>`:''}<div class="chart-grid-wrap">${chartDefs.map(d=>{const vals=e.points.map(p=>d.series[0].value(p)).filter(Number.isFinite),avg=vals.reduce((a,b)=>a+b,0)/(vals.length||1),peak=Math.max(0,...vals);return `<figure class="chart-card"><figcaption><b>${d.title}</b><span class="muted">Ø ${esc(d.fmt(avg))} · Spitze ${esc(d.fmt(peak))}</span></figcaption>${d.series.length>1?`<div class="chart-legend">${d.series.map((s,i)=>`<span><i class="swatch series-${i+1}"></i>${s.label}</span>`).join('')}</div>`:''}${chartSVG(key+'|'+d.id,e.points,d.series,{max:d.max,fmt:d.fmt,span,label:`${d.title}, ${timeframes.find(t=>t[0]===tf)?.[1]}: Durchschnitt ${d.fmt(avg)}, Spitze ${d.fmt(peak)}`})}</figure>`}).join('')}</div></div>`}
function metricsPanel(kind,cid,node,vmid){const tf=state.rrdTimeframe||'hour',key=[kind,cid,node,vmid||'',tf].join('|');return `<section class="panel metrics-panel"><div class="table-toolbar"><h2>Leistung</h2><div class="filter-chips" role="group" aria-label="Zeitraum">${timeframes.map(([k,l])=>`<button type="button" class="chip ${tf===k?'selected':''}" data-rrd-tf="${k}" aria-pressed="${tf===k}">${l}</button>`).join('')}</div></div>${metricsCharts(key)}</section>`}
let hostChartRef=null;
function hostMetricsModal(cid,node){openModal('HOST-VERLAUF',node,`<div id="host-metrics">${metricsPanel('node',cid,node,'')}</div><div class="modal-foot"><button data-cancel>Schließen</button></div>`);hostChartRef={cid,node,epoch:modalEpoch};bindCharts(modal);for(const k of modal.querySelectorAll('[data-metrics-key]'))loadRRD(k.dataset.metricsKey)}
function bindCharts(root=document){
 for(const b of root.querySelectorAll('[data-rrd-tf]'))b.onclick=()=>{state.rrdTimeframe=b.dataset.rrdTf;if(root===modal&&hostChartRef&&hostChartRef.epoch===modalEpoch){const{cid,node}=hostChartRef;$('#host-metrics').innerHTML=metricsPanel('node',cid,node,'');bindCharts(modal);for(const k of modal.querySelectorAll('[data-metrics-key]'))loadRRD(k.dataset.metricsKey)}else render()};
 for(const el of root.querySelectorAll('[data-metrics-key]'))if(!rrdState()[el.dataset.metricsKey]?.at)loadRRD(el.dataset.metricsKey);
 for(const svg of root.querySelectorAll('svg.chart-svg')){const hit=svg.querySelector('.chart-hit'),cross=svg.querySelector('.chart-cross'),[kind,cid,node,vmid,tf,id]=svg.dataset.chart.split('|'),def=chartDefs.find(d=>d.id===id),pts=rrdState()[[kind,cid,node,vmid,tf].join('|')]?.points||[];let tip=svg.parentElement.querySelector('.chart-tip');if(!tip){tip=document.createElement('div');tip.className='chart-tip';tip.hidden=true;svg.parentElement.append(tip)}
  hit.onmousemove=e=>{const r=svg.getBoundingClientRect(),vb=svg.viewBox.baseVal,x=(e.clientX-r.left)/r.width*vb.width,first=pts[0]?.t,last=pts[pts.length-1]?.t,t=first+(x-44)/(vb.width-52)*(last-first);let best=pts[0];for(const p of pts)if(Math.abs(p.t-t)<Math.abs(best.t-t))best=p;const px=44+(best.t-first)/(last-first||1)*(vb.width-52);cross.setAttribute('x1',px);cross.setAttribute('x2',px);cross.setAttribute('visibility','visible');tip.hidden=false;tip.innerHTML=`<b>${new Date(best.t*1000).toLocaleString('de-DE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</b>${def.series.map((s,i)=>`<span>${def.series.length>1?`<i class="swatch series-${i+1}"></i>`:''}${s.label}: ${esc(def.fmt(s.value(best)))}</span>`).join('')}`;const left=(px/vb.width)*r.width;tip.style.left=Math.min(Math.max(left,70),r.width-70)+'px'};
  hit.onmouseleave=()=>{cross.setAttribute('visibility','hidden');tip.hidden=true}}
}
